package com.tripnest.service;
import com.tripnest.dto.ApiDtos.AccommodationView; import com.tripnest.entity.*; import com.tripnest.exception.ApiException; import com.tripnest.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class WishlistService { final WishlistRepository wishlists; final UserRepository users; final AccommodationRepository accommodations; final AccommodationService views; public WishlistService(WishlistRepository w,UserRepository u,AccommodationRepository a,AccommodationService v){wishlists=w;users=u;accommodations=a;views=v;} @Transactional(readOnly=true) public List<AccommodationView> list(String email){return wishlists.findByUserIdOrderByCreatedAtDesc(user(email).getId()).stream().map(x->views.view(x.getAccommodation())).toList();} @Transactional public void add(String email,Long id){User u=user(email);Accommodation a=accommodations.findByIdAndActiveTrue(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Accommodation not found."));if(!wishlists.existsByUserIdAndAccommodationId(u.getId(),id)){WishlistItem x=new WishlistItem();x.setUser(u);x.setAccommodation(a);wishlists.save(x);}} @Transactional public void remove(String email,Long id){wishlists.deleteByUserIdAndAccommodationId(user(email).getId(),id);} private User user(String email){return users.findByEmail(email).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Please sign in."));} }
